<template><section aria-label="血管活性药物映射管理"><p v-if="!allowed">仅超级管理员可管理全院药物语义映射。</p><template v-else><p>明确核对原实际药品身份、活性成分口径与允许的原速率单位。新映射先保存草稿，发布另行审核；没有自动临床映射。</p><el-button :disabled="saving" @click="creating=!creating">新建原药物映射草稿</el-button><el-button :loading="loading" @click="load">刷新原药物映射</el-button><el-form v-if="creating" label-position="top" :disabled="saving" @submit.prevent><el-input v-model="keyword" aria-label="实际药品检索词" placeholder="检索实际药品名称或条码" /><el-button :loading="searching" @click="search(1)">查询实际原药品身份</el-button><el-select v-model="pharmaId" aria-label="明确实际原药品" clearable placeholder="明确选择实际原药品，不按名称猜测"><el-option v-for="row in pharmaceuticals" :key="row.pharmaceutical_id" :value="row.pharmaceutical_id" :label="`${row.name} · ${row.barcode??'无条码'} · #${row.pharmaceutical_id}`" /></el-select><el-pagination v-if="pharmaTotal>20" v-model:current-page="pharmaPage" :page-size="20" :total="pharmaTotal" layout="prev,pager,next" @current-change="search" /><el-form-item v-for="[key,label,max] in fields" :key="key" :label="label"><el-input v-model="form[key]" :aria-label="label" :maxlength="max" :type="['rationale','evidence_reference'].includes(key)?'textarea':'text'" /></el-form-item><el-form-item label="明确药物语义"><el-select v-model="form.drug_key" aria-label="明确药物语义"><el-option v-for="(label,key) in drugs" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-form-item label="活性成分原口径"><el-select v-model="form.active_moiety_basis" aria-label="活性成分原口径"><el-option label="原游离碱口径" value="base" /><el-option label="原盐口径" value="salt" /><el-option label="原口径未知" value="unknown" /></el-select></el-form-item><el-checkbox-group v-model="form.allowed_rate_units" aria-label="实际允许原速率单位"><el-checkbox v-for="unit in units" :key="unit" :value="unit">{{ unit }}</el-checkbox></el-checkbox-group><el-button type="primary" :loading="saving" :disabled="!canCreate" @click="create">仅保存原药物映射草稿</el-button></el-form><p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p><el-table :data="items" aria-label="原药物映射目录"><el-table-column prop="name" label="原审核名称" /><el-table-column label="原实际药品"><template #default="{row}">{{ row.original_drug_identity.name }} · #{{ row.pharmaceutical_id }}<br />{{ row.source_namespace }}</template></el-table-column><el-table-column label="原语义与单位"><template #default="{row}">{{ row.drug_key }} · {{ row.active_moiety_basis }}<br />{{ row.allowed_rate_units.join('、') }}</template></el-table-column><el-table-column label="治理"><template #default="{row}">{{ row.status }} · v{{ row.revision }}<el-button @click="inspect(row)">核对原药物映射</el-button></template></el-table-column></el-table><el-pagination v-if="total>20" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load" /></template><el-dialog v-model="detailOpen" title="原药物映射独立审核" width="min(800px,95vw)" @closed="clearDetail"><template v-if="allowed&&detail"><p>{{ detail.name }} · {{ detail.mapping_id }} · {{ detail.status }} v{{ detail.revision }}</p><p>实际原药品 {{ detail.original_drug_identity.name }} · #{{ detail.pharmaceutical_id }} · {{ detail.original_drug_identity.barcode??'无条码' }}。</p><p>原语义 {{ detail.drug_key }}；活性口径 {{ detail.active_moiety_basis }}；原允许单位 {{ detail.allowed_rate_units.join('、') }}。</p><p>原依据 {{ detail.evidence_reference }}；原审核理由 {{ detail.rationale }}。完整摘要 {{ detail.content_hash }}。</p><p v-for="item in detail.exclusion_reasons" :key="item">{{ item }}</p><template v-if="detail.status==='draft'&&detail.original_identity_current"><el-checkbox v-model="checks.original_identity_confirmed">已核实原药品身份与条码</el-checkbox><el-checkbox v-model="checks.drug_semantics_confirmed">已核实药物与活性成分语义</el-checkbox><el-checkbox v-model="checks.rate_units_confirmed">已核实允许的原速率单位</el-checkbox><el-input v-model="review" aria-label="原药物映射发布审核依据" type="textarea" maxlength="2000" /><el-button type="primary" :disabled="!canPublish||saving" :loading="saving" @click="change('publish')">发布明确原药物映射</el-button></template><template v-if="detail.status!=='revoked'"><el-input v-model="reason" aria-label="原药物映射撤销依据" maxlength="1000" /><el-button type="danger" :disabled="reason.trim().length<5||saving" :loading="saving" @click="change('revoke')">撤销原药物映射</el-button></template></template><p v-if="detailError" role="alert">{{ detailError }}</p></el-dialog></section></template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { createVasoactiveMapping, getVasoactiveMapping, getVasoactiveMappingOptions, getVasoactiveMappings, publishVasoactiveMapping, revokeVasoactiveMapping, sameMappingContent, verifyVasoactiveMapping } from "@/api/vasoactiveMappings";
import { supportDigest, supportHash } from "@/api/inpatientSupport";
const props=defineProps({active:{type:Boolean,default:true}}),store=useStore(),roles=computed(()=>store.getters["user/permissions"]||[]),allowed=computed(()=>props.active&&!!store.state.user.accessToken&&roles.value.includes("super_admin"));
const drugs={dopamine:"多巴胺",dobutamine:"多巴酚丁胺",epinephrine:"肾上腺素",norepinephrine:"去甲肾上腺素",other:"其他明确原药物"},units=["ug/kg/min","ug/min","mg/h","mL/h"],fields=[["name","原药物映射审核名称",120],["source_namespace","原药物来源命名空间",120],["evidence_reference","原药物映射证据出处",1000],["rationale","原药物映射审核理由",2000]],blank=()=>({name:"",source_namespace:"",drug_key:"",active_moiety_basis:"",allowed_rate_units:[],evidence_reference:"",rationale:""});
const form=ref(blank()),creating=ref(false),items=ref([]),total=ref(null),page=ref(1),pharmaceuticals=ref([]),pharmaId=ref(null),keyword=ref(""),pharmaPage=ref(1),pharmaTotal=ref(null),loading=ref(false),searching=ref(false),saving=ref(false),error=ref(""),notice=ref(""),detail=ref(null),detailOpen=ref(false),detailError=ref(""),checks=ref({original_identity_confirmed:false,drug_semantics_confirmed:false,rate_units_confirmed:false}),review=ref(""),reason=ref("");
let epoch=0,listSeq=0,searchSeq=0,detailSeq=0,inactive=false;const scope=()=>JSON.stringify([props.active,store.state.user.accessToken,roles.value]),capture=()=>({epoch,key:scope()}),current=t=>t.epoch===epoch&&t.key===scope()&&allowed.value&&!inactive;
const pharma=computed(()=>pharmaceuticals.value.find(item=>item.pharmaceutical_id===pharmaId.value));
const canCreate=computed(()=>allowed.value&&!saving.value&&!!pharma.value&&fields.every(([key,,max])=>typeof form.value[key]==="string"&&form.value[key]===form.value[key].trim()&&form.value[key].length>=({name:1,source_namespace:2,evidence_reference:5,rationale:20}[key])&&form.value[key].length<=max)&&Object.hasOwn(drugs,form.value.drug_key)&&["base","salt","unknown"].includes(form.value.active_moiety_basis)&&form.value.allowed_rate_units.length>0),canPublish=computed(()=>allowed.value&&detail.value?.status==="draft"&&Object.values(checks.value).every(value=>value===true)&&review.value===review.value.trim()&&review.value.length>=20);
function clearDetail(){detailSeq++;detail.value=null;detailOpen.value=false;detailError.value=review.value=reason.value="";checks.value={original_identity_confirmed:false,drug_semantics_confirmed:false,rate_units_confirmed:false};}
function reset(){epoch++;listSeq++;searchSeq++;clearDetail();form.value=blank();creating.value=false;items.value=[];total.value=null;page.value=pharmaPage.value=1;pharmaceuticals.value=[];pharmaId.value=null;keyword.value="";pharmaTotal.value=null;loading.value=searching.value=saving.value=false;error.value=notice.value="";}
async function load(){if(!allowed.value||inactive)return;const t=capture(),seq=++listSeq;loading.value=true;items.value=[];error.value="";try{const response=await getVasoactiveMappings({page:page.value,page_size:20}),data=response.data;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.total<0)throw new Error("原药物映射目录不完整");for(const row of data.items)if(!await verifyVasoactiveMapping(row))throw new Error("原药物映射目录身份、正文或治理摘要不一致");if(current(t)&&seq===listSeq){items.value=data.items;total.value=data.total;}}catch(failure){if(current(t)&&seq===listSeq)error.value=failure?.message||"映射目录读取失败";}finally{if(current(t)&&seq===listSeq)loading.value=false;}}
async function search(nextPage){if(!allowed.value||inactive)return;const t=capture(),seq=++searchSeq,word=keyword.value;pharmaPage.value=nextPage;searching.value=true;pharmaceuticals.value=[];pharmaId.value=null;error.value="";try{const response=await getVasoactiveMappingOptions({keyword:word,page:nextPage,page_size:20}),data=response.data?.pharmaceuticals;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total))throw new Error("实际原药品目录不完整");for(const row of data.items){if(!Number.isSafeInteger(row.pharmaceutical_id)||row.pharmaceutical_id<1||typeof row.name!=="string"||!supportHash(row.original_drug_identity_hash)||await supportDigest({pharmaceutical_id:row.pharmaceutical_id,name:row.name,barcode:row.barcode})!==row.original_drug_identity_hash)throw new Error("实际原药品身份或摘要不一致");}if(current(t)&&seq===searchSeq&&word===keyword.value){pharmaceuticals.value=data.items;pharmaTotal.value=data.total;}}catch(failure){if(current(t)&&seq===searchSeq)error.value=failure?.message||"原药品查询失败";}finally{if(current(t)&&seq===searchSeq)searching.value=false;}}
async function create(){if(!canCreate.value||inactive)return;const t=capture(),body={...form.value,allowed_rate_units:[...form.value.allowed_rate_units],pharmaceutical_id:pharma.value.pharmaceutical_id,expected_original_drug_identity_hash:pharma.value.original_drug_identity_hash};saving.value=true;error.value="";try{const response=await createVasoactiveMapping(body),row=response.data;if(!current(t))return;if(!await verifyVasoactiveMapping(row)||row.status!=="draft"||row.revision!==1||Object.keys(body).some(key=>JSON.stringify(body[key])!==JSON.stringify(row[key])))throw new Error("原药物映射草稿回执与明确原身份、语义或单位不一致");if(!current(t))return;form.value=blank();pharmaId.value=null;creating.value=false;notice.value="原药物映射草稿已保存；须独立审核发布，未启用AI或临床验证。";await load();}catch(failure){if(current(t))error.value=failure?.message||"草稿保存失败";}finally{if(current(t))saving.value=false;}}
async function inspect(row){clearDetail();if(!allowed.value||inactive)return;const t=capture(),seq=detailSeq;detailOpen.value=true;try{const response=await getVasoactiveMapping(row.mapping_id),value=response.data;if(!current(t)||seq!==detailSeq)return;if(!await verifyVasoactiveMapping(value)||value.mapping_id!==row.mapping_id||value.content_hash!==row.content_hash)throw new Error("原药物映射详情与明确原版本不一致");if(current(t)&&seq===detailSeq)detail.value=value;}catch(failure){if(current(t)&&seq===detailSeq)detailError.value=failure?.message||"映射详情读取失败";}}
async function change(action){if(!allowed.value||inactive||saving.value||!detail.value||action==="publish"&&!canPublish.value||action==="revoke"&&reason.value.trim().length<5)return;const original=detail.value,t=capture(),seq=detailSeq,body=action==="publish"?{expected_revision:original.revision,...checks.value,review_note:review.value}:{expected_revision:original.revision,reason:reason.value};saving.value=true;detailError.value="";try{const response=await(action==="publish"?publishVasoactiveMapping:revokeVasoactiveMapping)(original.mapping_id,body),row=response.data;if(!current(t)||seq!==detailSeq)return;if(!await verifyVasoactiveMapping(row)||!sameMappingContent(original,row)||row.mapping_id!==original.mapping_id||row.content_hash!==original.content_hash||row.revision!==original.revision+1||row.status!==(action==="publish"?"published":"revoked"))throw new Error("原药物映射治理回执与原身份、正文或预期版本不一致");if(!current(t)||seq!==detailSeq)return;clearDetail();notice.value=action==="publish"?"明确原药物映射已审核发布；不表示患者实际给药或临床效果已验证。":"原药物映射已撤销，原依赖资料须重新核对。";await load();}catch(failure){if(current(t)&&seq===detailSeq)detailError.value=failure?.message||"原映射版本已变化，请重新核对";}finally{if(current(t))saving.value=false;}}
watch(scope,()=>{reset();load();},{immediate:true,flush:"sync"});watch(keyword,()=>{searchSeq++;pharmaceuticals.value=[];pharmaId.value=null;pharmaTotal.value=null;});onDeactivated(()=>{inactive=true;reset();});onActivated(()=>{if(inactive){inactive=false;reset();load();}});onBeforeUnmount(()=>{inactive=true;reset();});
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere}.el-select{width:100%}.el-checkbox{display:block;height:auto;white-space:normal;margin:12px 0}.el-input{margin:8px 0}.el-button{margin:8px 8px 8px 0}</style>
